const address = document.getElementById('address');
const canvas = document.getElementById('screen');
const context = canvas.getContext('2d', { alpha: false });
const viewport = document.getElementById('viewport');
const stage = document.getElementById('stage');
const browserShell = document.querySelector('.browser-shell');
const empty = document.getElementById('empty');
const emptyTitle = document.getElementById('empty-title');
const status = document.getElementById('status');
const connection = document.getElementById('connection');
const keyInput = document.getElementById('key-input');
const menu = document.getElementById('menu');
const remoteCursor = document.getElementById('remote-cursor');
const cursorImage = document.getElementById('cursor-image');
const selectionActions = document.getElementById('selection-actions');
const keyboardToggle = document.getElementById('keyboard-toggle');
const keyboardPanel = document.getElementById('pc-keyboard');
const keyboardResize = document.getElementById('keyboard-resize');
const rotateButtons = [document.getElementById('rotate'), document.getElementById('rotate-view')];
if (!teydra.orientation?.toggle) rotateButtons.forEach((button) => { button.hidden = true; });

const MOVE_THRESHOLD_PX = 10;
const LONG_PRESS_MS = 520;
const DOUBLE_TAP_MS = 280;
const DOUBLE_TAP_DISTANCE_PX = 26;
const SELECTION_MOVE_INTERVAL_MS = 120;
const SCROLL_INTERVAL_MS = 55;
const MAX_ZOOM = 4;
const EDGE_MARGIN_PX = 38;
const EDGE_PAN_MAX_PX = 7;
const MIN_KEYBOARD_HEIGHT_PX = 188;

canvas.width = 0;
canvas.height = 0;
let latest = null;
let revision = null;
let displayedUrl = null;
let stopped = false;
let drag = null;
let pinch = null;
let mode = 'direct';
let localCursor = { x: 640, y: 360, actor: 'human' };
let view = { zoom: 1, panX: 0, panY: 0 };
let layout = { left: 0, top: 0, scale: 1 };
let selectionMoveTimer = null;
let pendingSelectionPoint = null;
let pendingMouseTap = null;
let cursorAppearanceRevision = null;
let cursorAppearance = null;
let keyboardOpen = false;
let keyboardResizeGesture = null;
const activePointers = new Map();
const activeKeyboardModifiers = new Set();
let typedTail = Promise.resolve();
let controlTail = Promise.resolve();

function normalizedUrl(value) {
  const clean = value.trim();
  if (!clean) return null;
  if (/^https?:\/\//i.test(clean)) return clean;
  if (/^[a-z0-9.-]+\.[a-z]{2,}(?:[/:?#]|$)/i.test(clean)) return `https://${clean}`;
  return `https://www.google.com/search?q=${encodeURIComponent(clean)}`;
}

async function applySnapshot(snapshot) {
  if (!snapshot || typeof snapshot !== 'object') return false;
  if (snapshot.state === 'waiting') {
    showWaitingBrowser();
    latest = null;
    displayedUrl = null;
    address.value = '';
    document.getElementById('back').disabled = true;
    document.getElementById('forward').disabled = true;
    connection.classList.add('online');
    connection.title = 'PC verbunden';
    return true;
  }
  setBrowserWaiting(false);
  const isBlankPage = isBlankBrowserPage(snapshot.url);
  if (isBlankPage) showBlankBrowser();
  latest = snapshot;
  if (snapshot.frame) {
    if (!await applyFrame(snapshot.frame)) return false;
    if (typeof snapshot.url === 'string') displayedUrl = snapshot.url;
  }
  if (typeof snapshot.url === 'string' && document.activeElement !== address) {
    address.value = isBlankPage ? '' : snapshot.url;
  }
  document.getElementById('back').disabled = !snapshot.canGoBack;
  document.getElementById('forward').disabled = !snapshot.canGoForward;
  if (snapshot.cursorAppearance) applyCursorAppearance(snapshot.cursorAppearance);
  if (snapshot.cursor && !(mode === 'mouse' && drag)) localCursor = snapshot.cursor;
  layoutSurface();
  updateSelectionAction();
  connection.classList.add('online');
  connection.title = 'PC verbunden';
  if (isBlankPage) {
    showBlankBrowser();
  } else if (canvas.width > 0 && !isBlankBrowserPage(displayedUrl)) {
    empty.classList.remove('ready');
    empty.classList.add('hidden');
  } else {
    showBrowserLoading();
  }
  return true;
}

function isBlankBrowserPage(url) {
  return url === 'about:blank' || url === 'chrome://newtab/' || url === 'chrome://new-tab-page/' ||
    url === 'edge://newtab/';
}

function showBlankBrowser() {
  setBrowserWaiting(true);
  emptyTitle.textContent = 'Gemeinsamer PC-Tab';
  status.textContent = 'Codex hat noch keine Webseite geöffnet.';
  empty.classList.add('ready');
  empty.classList.remove('hidden');
}

function showWaitingBrowser() {
  setBrowserWaiting(true);
  emptyTitle.textContent = 'Noch kein gemeinsamer PC-Tab';
  status.textContent = 'Warte, bis Codex in diesem Chat eine Webseite öffnet.';
  empty.classList.add('ready');
  empty.classList.remove('hidden');
}

function setBrowserWaiting(waiting) {
  browserShell.classList.toggle('waiting', waiting);
  address.disabled = waiting;
  address.placeholder = waiting ? 'Wartet auf Codex' : 'Adresse oder Suche';
  document.getElementById('menu-button').disabled = waiting;
  if (waiting) {
    menu.classList.add('hidden');
    setKeyboardOpen(false);
  }
}

function showBrowserLoading() {
  emptyTitle.textContent = 'Gemeinsamer PC-Tab';
  status.textContent = 'Seite wird geladen …';
  empty.classList.remove('ready');
  empty.classList.remove('hidden');
}

async function applyFrame(frame) {
  if (frame.protocol !== 1 || !Array.isArray(frame.steps)) return false;
  if (!frame.reset && revision !== frame.baseRevision) {
    revision = null;
    return false;
  }
  if (frame.reset) {
    canvas.width = frame.width;
    canvas.height = frame.height;
    context.fillStyle = '#ffffff';
    context.fillRect(0, 0, canvas.width, canvas.height);
  }
  for (const step of frame.steps) {
    if (step.type === 'move') applyMove(step);
    if (step.type === 'paint') applyPaint(step);
    if (step.type === 'image') await applyImage(step);
  }
  revision = frame.revision;
  return true;
}

function applyMove(step) {
  const copy = document.createElement('canvas');
  copy.width = step.width;
  copy.height = step.height;
  copy.getContext('2d', { alpha: false }).drawImage(
    canvas,
    step.sourceX, step.sourceY, step.width, step.height,
    0, 0, step.width, step.height,
  );
  context.drawImage(copy, step.targetX, step.targetY);
}

function applyPaint(step) {
  if (!Array.isArray(step.boxes)) return;
  for (const box of step.boxes) {
    if (!Array.isArray(box) || box.length !== 5) continue;
    const [x, y, width, height, color] = box;
    context.fillStyle = `#${Number(color).toString(16).padStart(6, '0')}`;
    context.fillRect(x, y, width, height);
  }
}

function applyImage(step) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => {
      context.drawImage(image, step.x, step.y, step.width, step.height);
      resolve();
    };
    image.onerror = () => reject(new Error('Ein Browser-Bildausschnitt war beschädigt.'));
    image.src = `data:${step.mimeType};base64,${step.data}`;
  });
}

function applyFailure(error) {
  connection.classList.remove('online');
  connection.title = 'PC getrennt';
  status.textContent = error instanceof Error ? error.message : 'Der PC antwortet nicht.';
  empty.classList.remove('ready');
  if (canvas.width === 0 || isBlankBrowserPage(displayedUrl)) empty.classList.remove('hidden');
}

function control(actionId, input = {}) {
  const result = controlTail.then(async () => {
    if (stopped) return null;
    try {
      const snapshot = await teydra.query(actionId, {
        ...input,
        frameRevision: revision,
        cursorAppearanceRevision,
      });
      await applySnapshot(snapshot);
      return snapshot;
    } catch (error) {
      applyFailure(error);
      return null;
    }
  });
  controlTail = result.then(() => undefined, () => undefined);
  return result;
}

async function streamFrames() {
  while (!stopped) {
    try {
      const action = revision === null ? 'browser.start' : 'browser.snapshot';
      const snapshot = await teydra.query(action, { frameRevision: revision, cursorAppearanceRevision });
      await applySnapshot(snapshot);
      if (snapshot?.state === 'waiting') await wait(1_000);
    } catch (error) {
      applyFailure(error);
      await wait(1_000);
    }
  }
}

document.getElementById('address-form').addEventListener('submit', async (event) => {
  event.preventDefault();
  const url = normalizedUrl(address.value);
  if (!url) return;
  address.blur();
  await control('browser.navigate', { url });
});

document.getElementById('back').addEventListener('click', () => control('browser.back'));
document.getElementById('forward').addEventListener('click', () => closeMenu(control('browser.forward')));
document.getElementById('reload').addEventListener('click', () => closeMenu(control('browser.reload')));
document.getElementById('menu-button').addEventListener('click', () => menu.classList.toggle('hidden'));
rotateButtons.forEach((button) => button.addEventListener('click', async () => {
  menu.classList.add('hidden');
  try { await teydra.orientation?.toggle?.(); } catch (error) { applyFailure(error); }
}));

async function copySelectionToPhone() {
  menu.classList.add('hidden');
  try {
    if (!latest?.selection) throw new Error('Im Browser ist kein Text ausgewählt.');
    await teydra.clipboard.write(latest.selection);
  } catch (error) {
    status.textContent = error instanceof Error ? error.message : 'Kopieren wurde nicht erlaubt.';
  }
}

async function copySelectionToPc() {
  menu.classList.add('hidden');
  if (!latest?.selection) {
    status.textContent = 'Im Browser ist kein Text ausgewählt.';
    return;
  }
  const snapshot = await control('browser.copy');
  if (snapshot) status.textContent = 'Auf dem PC kopiert.';
}

document.getElementById('copy').addEventListener('click', copySelectionToPhone);
document.getElementById('copy-pc').addEventListener('click', copySelectionToPc);
document.getElementById('copy-selection-phone').addEventListener('click', copySelectionToPhone);
document.getElementById('copy-selection-pc').addEventListener('click', copySelectionToPc);
document.getElementById('direct-mode').addEventListener('click', () => setMode('direct'));
document.getElementById('mouse-mode').addEventListener('click', () => setMode('mouse'));
keyboardToggle.addEventListener('click', () => setKeyboardOpen(!keyboardOpen));

viewport.addEventListener('contextmenu', (event) => event.preventDefault());
viewport.addEventListener('pointerdown', (event) => {
  if (isAppletControl(event.target) || !latest) return;
  if (mode === 'direct' && !isOnBrowserImage(event.clientX, event.clientY)) return;
  viewport.setPointerCapture(event.pointerId);
  activePointers.set(event.pointerId, pointerPosition(event));
  if (activePointers.size >= 2) {
    beginPinch();
    return;
  }
  const point = mode === 'direct'
    ? remotePoint(event.clientX, event.clientY)
    : { x: localCursor.x, y: localCursor.y };
  drag = {
    id: event.pointerId,
    startClientX: event.clientX,
    startClientY: event.clientY,
    lastClientX: event.clientX,
    lastClientY: event.clientY,
    startedAt: performance.now(),
    point,
    cursor: { ...localCursor },
    moved: false,
    selecting: false,
    holdTimer: null,
    scrollClientX: event.clientX,
    scrollClientY: event.clientY,
    scrollDeltaX: 0,
    scrollDeltaY: 0,
    scrollTimer: null,
  };
  if (mode === 'direct') {
    drag.holdTimer = setTimeout(() => {
      if (!drag || drag.id !== event.pointerId || drag.moved || activePointers.size !== 1) return;
      drag.selecting = true;
      void control('browser.drag', { phase: 'start', x: drag.point.x, y: drag.point.y });
    }, LONG_PRESS_MS);
  }
});

viewport.addEventListener('pointermove', (event) => {
  if (!activePointers.has(event.pointerId)) return;
  activePointers.set(event.pointerId, pointerPosition(event));
  if (pinch && activePointers.size >= 2) {
    updatePinch();
    return;
  }
  if (!drag || drag.id !== event.pointerId) return;
  drag.lastClientX = event.clientX;
  drag.lastClientY = event.clientY;
  const dx = event.clientX - drag.startClientX;
  const dy = event.clientY - drag.startClientY;
  if (Math.abs(dx) + Math.abs(dy) > MOVE_THRESHOLD_PX) {
    drag.moved = true;
    if (!drag.selecting) clearDragHold();
    if (mode === 'mouse') flushPendingMouseTap();
  }
  if (drag.selecting) {
    scheduleSelectionMove(remotePoint(event.clientX, event.clientY));
    return;
  }
  if (mode === 'mouse') {
    localCursor = {
      x: clamp(drag.cursor.x + dx / layout.scale, 0, canvas.width),
      y: clamp(drag.cursor.y + dy / layout.scale, 0, canvas.height),
      actor: 'human',
    };
    placeCursor();
    panAtCursorEdge();
  } else if (drag.moved) {
    scheduleDirectScroll(event.clientX, event.clientY);
  }
});

viewport.addEventListener('pointerup', (event) => { void finishPointer(event); });
viewport.addEventListener('pointercancel', (event) => { void cancelPointer(event.pointerId); });

async function finishPointer(event) {
  activePointers.delete(event.pointerId);
  if (pinch) {
    if (activePointers.size < 2) pinch = null;
    drag = null;
    return;
  }
  if (!drag || drag.id !== event.pointerId) return;
  const start = drag;
  drag = null;
  clearTimeout(start.holdTimer);
  if (!latest) return;
  const point = remotePoint(event.clientX, event.clientY);
  if (start.selecting) {
    clearSelectionMove();
    await control('browser.drag', { phase: 'move', x: point.x, y: point.y });
    await control('browser.drag', { phase: 'end', x: point.x, y: point.y });
    return;
  }
  if (mode === 'mouse') {
    if (start.moved) {
      await control('browser.move', { x: localCursor.x, y: localCursor.y });
      return;
    }
    await handleMouseTap(performance.now() - start.startedAt);
    return;
  }
  if (start.moved) {
    clearTimeout(start.scrollTimer);
    start.scrollDeltaX += (start.scrollClientX - event.clientX) / layout.scale;
    start.scrollDeltaY += (start.scrollClientY - event.clientY) / layout.scale;
    start.scrollClientX = event.clientX;
    start.scrollClientY = event.clientY;
    await flushDirectScroll(start);
  } else {
    const snapshot = await control('browser.pointer', point);
    if (snapshot?.acceptsText && !keyboardOpen) keyInput.focus();
  }
}

async function handleMouseTap(duration) {
  const point = { x: localCursor.x, y: localCursor.y };
  if (duration >= LONG_PRESS_MS) {
    cancelPendingMouseTap();
    await clickMouseCursor(point, 'right');
    return;
  }
  const now = performance.now();
  if (
    pendingMouseTap && now - pendingMouseTap.at <= DOUBLE_TAP_MS &&
    distance(point, pendingMouseTap.point) <= DOUBLE_TAP_DISTANCE_PX
  ) {
    cancelPendingMouseTap();
    await clickMouseCursor(point, 'right');
    return;
  }
  cancelPendingMouseTap();
  const timer = setTimeout(() => {
    const pending = pendingMouseTap;
    pendingMouseTap = null;
    if (pending) void clickMouseCursor(pending.point, 'left');
  }, DOUBLE_TAP_MS);
  pendingMouseTap = { at: now, point, timer };
}

async function clickMouseCursor(point, button) {
  const snapshot = await control('browser.pointer', { ...point, button });
  if (button === 'left' && snapshot?.acceptsText && !keyboardOpen) keyInput.focus();
}

function cancelPendingMouseTap() {
  if (pendingMouseTap) clearTimeout(pendingMouseTap.timer);
  pendingMouseTap = null;
}

function flushPendingMouseTap() {
  const pending = pendingMouseTap;
  cancelPendingMouseTap();
  if (pending) void clickMouseCursor(pending.point, 'left');
}

async function cancelPointer(pointerId) {
  activePointers.delete(pointerId);
  if (!drag || drag.id !== pointerId) return;
  const cancelled = drag;
  drag = null;
  clearTimeout(cancelled.holdTimer);
  clearTimeout(cancelled.scrollTimer);
  clearSelectionMove();
  if (cancelled.selecting) {
    const point = remotePoint(cancelled.lastClientX, cancelled.lastClientY);
    await control('browser.drag', { phase: 'end', x: point.x, y: point.y });
  }
}

function scheduleDirectScroll(clientX, clientY) {
  if (!drag) return;
  drag.scrollDeltaX += (drag.scrollClientX - clientX) / layout.scale;
  drag.scrollDeltaY += (drag.scrollClientY - clientY) / layout.scale;
  drag.scrollClientX = clientX;
  drag.scrollClientY = clientY;
  if (drag.scrollTimer) return;
  const current = drag;
  current.scrollTimer = setTimeout(() => {
    current.scrollTimer = null;
    void flushDirectScroll(current);
  }, SCROLL_INTERVAL_MS);
}

function flushDirectScroll(scroll) {
  const deltaX = scroll.scrollDeltaX;
  const deltaY = scroll.scrollDeltaY;
  scroll.scrollDeltaX = 0;
  scroll.scrollDeltaY = 0;
  if (Math.abs(deltaX) + Math.abs(deltaY) < 0.5) return Promise.resolve(null);
  const point = remotePoint(scroll.scrollClientX, scroll.scrollClientY);
  return control('browser.scroll', { x: point.x, y: point.y, deltaX, deltaY });
}

function beginPinch() {
  clearDragHold();
  if (drag?.scrollTimer) clearTimeout(drag.scrollTimer);
  drag = null;
  const points = [...activePointers.values()].slice(0, 2);
  const center = midpoint(points[0], points[1]);
  pinch = {
    distance: Math.max(1, distance(points[0], points[1])),
    zoom: view.zoom,
    anchor: remotePoint(center.x, center.y),
  };
}

function updatePinch() {
  const points = [...activePointers.values()].slice(0, 2);
  if (points.length < 2) return;
  const center = midpoint(points[0], points[1]);
  const zoom = clamp(pinch.zoom * distance(points[0], points[1]) / pinch.distance, 1, MAX_ZOOM);
  const viewportBox = viewport.getBoundingClientRect();
  const fitScale = Math.min(viewportBox.width / canvas.width, viewportBox.height / canvas.height);
  const scale = fitScale * zoom;
  const width = canvas.width * scale;
  const height = canvas.height * scale;
  view = {
    zoom,
    panX: center.x - viewportBox.left - pinch.anchor.x * scale - (viewportBox.width - width) / 2,
    panY: center.y - viewportBox.top - pinch.anchor.y * scale - (viewportBox.height - height) / 2,
  };
  layoutSurface();
}

function scheduleSelectionMove(point) {
  pendingSelectionPoint = point;
  if (selectionMoveTimer) return;
  selectionMoveTimer = setTimeout(() => {
    selectionMoveTimer = null;
    const next = pendingSelectionPoint;
    pendingSelectionPoint = null;
    if (next) void control('browser.drag', { phase: 'move', x: next.x, y: next.y });
  }, SELECTION_MOVE_INTERVAL_MS);
}

function clearSelectionMove() {
  if (selectionMoveTimer) clearTimeout(selectionMoveTimer);
  selectionMoveTimer = null;
  pendingSelectionPoint = null;
}

function clearDragHold() {
  if (drag?.holdTimer) clearTimeout(drag.holdTimer);
  if (drag) drag.holdTimer = null;
}

keyInput.addEventListener('input', () => {
  const text = keyInput.value;
  keyInput.value = '';
  if (!text) return;
  typedTail = typedTail.then(() => control('browser.type', { text }));
});
keyInput.addEventListener('keydown', (event) => {
  if (![
    'Enter', 'Backspace', 'Tab', 'Escape', 'Delete', 'Home', 'End', 'PageUp', 'PageDown',
    'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
  ].includes(event.key)) return;
  event.preventDefault();
  typedTail = typedTail.then(() => control('browser.key', { key: event.key }));
});

document.querySelectorAll('[data-pc-key]').forEach((button) => {
  button.addEventListener('click', () => pressPcKey(Number(button.dataset.pcKey)));
});

keyboardResize.addEventListener('pointerdown', (event) => {
  keyboardResize.setPointerCapture(event.pointerId);
  keyboardResizeGesture = {
    id: event.pointerId,
    startY: event.clientY,
    startHeight: keyboardPanel.getBoundingClientRect().height,
  };
});
keyboardResize.addEventListener('pointermove', (event) => {
  if (!keyboardResizeGesture || keyboardResizeGesture.id !== event.pointerId) return;
  setKeyboardHeight(keyboardResizeGesture.startHeight + keyboardResizeGesture.startY - event.clientY);
});
keyboardResize.addEventListener('pointerup', (event) => {
  if (keyboardResizeGesture?.id === event.pointerId) keyboardResizeGesture = null;
});
keyboardResize.addEventListener('pointercancel', () => { keyboardResizeGesture = null; });

function pressPcKey(index) {
  const key = PC_KEY_ROWS.flat()[index];
  if (!key) return;
  if (key.modifiers) {
    const isActive = key.modifiers.every((modifier) => activeKeyboardModifiers.has(modifier));
    for (const modifier of key.modifiers) {
      if (isActive) activeKeyboardModifiers.delete(modifier);
      else activeKeyboardModifiers.add(modifier);
    }
    updateModifierKeys();
    return;
  }
  const modifiers = [...activeKeyboardModifiers];
  const hasOnlyShift = modifiers.length === 1 && modifiers[0] === 'shift';
  if (key.text !== undefined && (modifiers.length === 0 || hasOnlyShift)) {
    const text = hasOnlyShift ? key.shift ?? key.text.toLocaleUpperCase('de-DE') : key.text;
    typedTail = typedTail.then(() => control('browser.type', { text }));
  } else {
    typedTail = typedTail.then(() => control('browser.key', {
      key: key.key ?? key.text,
      modifiers,
    }));
  }
  activeKeyboardModifiers.clear();
  updateModifierKeys();
}

function updateModifierKeys() {
  document.querySelectorAll('[data-pc-key]').forEach((button) => {
    const key = PC_KEY_ROWS.flat()[Number(button.dataset.pcKey)];
    const active = Boolean(key?.modifiers?.every((modifier) => activeKeyboardModifiers.has(modifier)));
    button.classList.toggle('modifier-active', active);
    if (key?.modifiers) button.setAttribute('aria-pressed', String(active));
  });
}

function setKeyboardOpen(next) {
  keyboardOpen = Boolean(next && isLandscape());
  keyboardPanel.classList.toggle('open', keyboardOpen);
  keyboardPanel.setAttribute('aria-hidden', String(!keyboardOpen));
  keyboardToggle.classList.toggle('active', keyboardOpen);
  keyboardToggle.setAttribute('aria-pressed', String(keyboardOpen));
  if (keyboardOpen) {
    keyInput.blur();
    if (!keyboardPanel.style.height) setKeyboardHeight(document.documentElement.clientHeight * 0.47);
  } else {
    activeKeyboardModifiers.clear();
    updateModifierKeys();
  }
  requestAnimationFrame(layoutSurface);
}

function setKeyboardHeight(height) {
  const shellHeight = document.querySelector('.browser-shell').clientHeight;
  const maximum = Math.max(MIN_KEYBOARD_HEIGHT_PX, shellHeight - 112);
  keyboardPanel.style.height = `${clamp(height, MIN_KEYBOARD_HEIGHT_PX, maximum)}px`;
  requestAnimationFrame(layoutSurface);
}

function setMode(next) {
  mode = next;
  cancelPendingMouseTap();
  clearDragHold();
  clearSelectionMove();
  drag = null;
  activePointers.clear();
  document.getElementById('direct-mode').classList.toggle('active', next === 'direct');
  document.getElementById('mouse-mode').classList.toggle('active', next === 'mouse');
  placeCursor();
}

function layoutSurface() {
  if (!canvas.width || !canvas.height) return;
  const viewportBox = viewport.getBoundingClientRect();
  const fitScale = Math.min(viewportBox.width / canvas.width, viewportBox.height / canvas.height);
  const scale = fitScale * view.zoom;
  const width = canvas.width * scale;
  const height = canvas.height * scale;
  const maxPanX = Math.max(0, (width - viewportBox.width) / 2);
  const maxPanY = Math.max(0, (height - viewportBox.height) / 2);
  view.panX = clamp(view.panX, -maxPanX, maxPanX);
  view.panY = clamp(view.panY, -maxPanY, maxPanY);
  layout = {
    left: (viewportBox.width - width) / 2 + view.panX,
    top: (viewportBox.height - height) / 2 + view.panY,
    scale,
  };
  stage.style.width = `${canvas.width}px`;
  stage.style.height = `${canvas.height}px`;
  stage.style.transform = `translate3d(${layout.left}px, ${layout.top}px, 0) scale(${scale})`;
  placeCursor();
}

function placeCursor() {
  if (!canvas.width) return;
  const left = layout.left + localCursor.x * layout.scale;
  const top = layout.top + localCursor.y * layout.scale;
  const appearance = cursorAppearance?.[localCursor.actor];
  if (appearance) {
    const source = `data:${appearance.mimeType};base64,${appearance.data}`;
    if (cursorImage.src !== source) cursorImage.src = source;
    cursorImage.style.width = `${appearance.width}px`;
    cursorImage.style.height = `${appearance.height}px`;
  }
  const hotspotX = appearance?.hotspotX ?? 3;
  const hotspotY = appearance?.hotspotY ?? 2;
  remoteCursor.style.transform = `translate3d(${left - hotspotX}px, ${top - hotspotY}px, 0)`;
  remoteCursor.classList.toggle('ai', localCursor.actor === 'ai');
  remoteCursor.classList.toggle('visible', mode === 'mouse' || localCursor.actor === 'ai');
  placeSelectionAction(left, top);
}

function applyCursorAppearance(value) {
  if (!value || typeof value !== 'object' || typeof value.revision !== 'string') return;
  const human = validCursorImage(value.human);
  const ai = validCursorImage(value.ai);
  if (!human || !ai) return;
  cursorAppearanceRevision = value.revision;
  cursorAppearance = { human, ai };
  remoteCursor.classList.add('has-image');
}

function validCursorImage(value) {
  if (
    !value || typeof value !== 'object' || value.mimeType !== 'image/svg+xml' ||
    typeof value.data !== 'string' || value.data.length > 16_000 ||
    !Number.isFinite(value.width) || value.width < 8 || value.width > 96 ||
    !Number.isFinite(value.height) || value.height < 8 || value.height > 96 ||
    !Number.isFinite(value.hotspotX) || !Number.isFinite(value.hotspotY)
  ) return null;
  return value;
}

function placeSelectionAction(cursorLeft, cursorTop) {
  if (!selectionActions.classList.contains('visible')) return;
  const width = viewport.clientWidth;
  const height = viewport.clientHeight;
  const actionWidth = selectionActions.offsetWidth || 180;
  const left = clamp(cursorLeft + 20, 8, Math.max(8, width - actionWidth - 8));
  const preferredTop = cursorTop > 54 ? cursorTop - 42 : cursorTop + 30;
  selectionActions.style.transform = `translate3d(${left}px, ${clamp(preferredTop, 8, Math.max(8, height - 40))}px, 0)`;
}

function updateSelectionAction() {
  const visible = typeof latest?.selection === 'string' && latest.selection.trim().length > 0;
  selectionActions.classList.toggle('visible', visible);
  placeCursor();
}

function panAtCursorEdge() {
  if (view.zoom <= 1) return;
  const cursorLeft = layout.left + localCursor.x * layout.scale;
  const cursorTop = layout.top + localCursor.y * layout.scale;
  const rightEdge = viewport.clientWidth - EDGE_MARGIN_PX;
  const bottomEdge = viewport.clientHeight - EDGE_MARGIN_PX;
  if (cursorLeft < EDGE_MARGIN_PX) view.panX += edgeStep(EDGE_MARGIN_PX - cursorLeft);
  if (cursorLeft > rightEdge) view.panX -= edgeStep(cursorLeft - rightEdge);
  if (cursorTop < EDGE_MARGIN_PX) view.panY += edgeStep(EDGE_MARGIN_PX - cursorTop);
  if (cursorTop > bottomEdge) view.panY -= edgeStep(cursorTop - bottomEdge);
  layoutSurface();
}

function edgeStep(distanceFromEdge) {
  return Math.min(EDGE_PAN_MAX_PX, 1 + distanceFromEdge * 0.16);
}

function remotePoint(clientX, clientY) {
  const box = viewport.getBoundingClientRect();
  return {
    x: clamp((clientX - box.left - layout.left) / layout.scale, 0, canvas.width),
    y: clamp((clientY - box.top - layout.top) / layout.scale, 0, canvas.height),
  };
}

function pointerPosition(event) {
  return { x: event.clientX, y: event.clientY };
}

function isAppletControl(target) {
  return target instanceof Element && Boolean(target.closest('button, input, textarea, .keyboard-resize'));
}

function isOnBrowserImage(clientX, clientY) {
  const box = viewport.getBoundingClientRect();
  const left = box.left + layout.left;
  const top = box.top + layout.top;
  return clientX >= left && clientX <= left + canvas.width * layout.scale &&
    clientY >= top && clientY <= top + canvas.height * layout.scale;
}

function isLandscape() {
  return document.documentElement.clientWidth > document.documentElement.clientHeight;
}

function midpoint(first, second) {
  return { x: (first.x + second.x) / 2, y: (first.y + second.y) / 2 };
}

function distance(first, second) {
  return Math.hypot(second.x - first.x, second.y - first.y);
}

function pcKeyboardMarkup() {
  let index = 0;
  return PC_KEY_ROWS.map((row) => `
    <div class="keyboard-row">
      ${row.map((key) => {
        const keyIndex = index;
        index += 1;
        const pressed = key.modifiers ? ' aria-pressed="false"' : '';
        return `<button type="button" data-pc-key="${keyIndex}" style="--key-flex:${key.flex ?? 1}" aria-label="${key.label || 'Leertaste'}"${pressed}>${key.label}</button>`;
      }).join('')}
    </div>
  `).join('');
}

function closeMenu(promise) {
  menu.classList.add('hidden');
  return promise;
}

function clamp(value, minimum, maximum) {
  return Math.max(minimum, Math.min(maximum, value));
}

function wait(milliseconds) {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

window.addEventListener('resize', () => {
  if (keyboardOpen && !isLandscape()) setKeyboardOpen(false);
  layoutSurface();
});
window.addEventListener('beforeunload', () => {
  stopped = true;
  cancelPendingMouseTap();
  clearDragHold();
  clearSelectionMove();
});
