companionBundle.style:
:root {
  color-scheme: dark;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #090b0b;
  color: #f5f7f6;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body, #app { width: 100%; height: 100%; margin: 0; overflow: hidden; }
button, input, textarea { font: inherit; }
button { color: inherit; }
.browser-shell { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; background: #090b0b; }
.address-row {
  position: relative; z-index: 7; display: grid; grid-template-columns: 34px 8px minmax(0, 1fr) 38px;
  align-items: center; gap: 7px; padding: 7px 8px; border-bottom: 1px solid #202a27; background: #101413;
}
.address-row button { appearance: none; border: 0; border-radius: 10px; background: transparent; min-height: 36px; }
.address-row button:active { background: #26312e; transform: scale(.97); }
.address-row button:disabled { opacity: .26; }
.address-row .icon { font-size: 24px; line-height: 1; }
.menu-button { font-size: 15px !important; font-weight: 800; letter-spacing: 1px; }
.connection { width: 7px; height: 7px; border-radius: 50%; background: #6c7471; box-shadow: 0 0 0 2px #1d2321; }
.connection.online { background: #5bd5ad; box-shadow: 0 0 0 2px #143d30; }
#address {
  width: 100%; min-width: 0; min-height: 36px; border: 1px solid #293632; border-radius: 11px;
  outline: none; padding: 0 11px; background: #080a09; color: #edf5f2; font-size: 13px;
}
#address:focus { border-color: #40b995; box-shadow: 0 0 0 2px #174638; }
#address:disabled { color: #71807b; opacity: 1; }
.menu {
  position: absolute; top: 50px; right: 8px; width: 178px; display: grid; padding: 6px;
  border: 1px solid #33423d; border-radius: 13px; background: #171d1b; box-shadow: 0 12px 34px #0009;
}
.menu.hidden { display: none; }
.menu button { min-height: 39px; padding: 0 11px; text-align: left; font-size: 13px; }
.viewport { position: relative; min-height: 0; overflow: hidden; background: #151817; touch-action: none; }
.stage { position: absolute; left: 0; top: 0; transform-origin: 0 0; will-change: transform; }
#screen {
  display: block; width: 100%; height: 100%; background: #fff; user-select: none;
  -webkit-user-select: none; image-rendering: auto;
}
.empty {
  position: absolute; z-index: 2; inset: 0; display: grid; place-content: center; justify-items: center; gap: 9px;
  padding: 30px; color: #e8efed; text-align: center; background: radial-gradient(circle at 50% 43%, #17241f, #0d1110 55%);
}
.empty.hidden { display: none; }
.empty.ready .pulse { display: none; }
.empty span { max-width: 280px; color: #8d9d98; font-size: 13px; line-height: 1.45; }
.pulse { width: 38px; height: 38px; margin-bottom: 7px; border: 2px solid #2b6d59; border-top-color: #70dfbd; border-radius: 50%; animation: turn 1s linear infinite; }
.mode-switch {
  position: absolute; z-index: 5; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom)); display: flex;
  padding: 3px; border: 1px solid #ffffff1f; border-radius: 12px; background: #0d1210dd; backdrop-filter: blur(12px);
}
.mode-switch button { appearance: none; min-height: 30px; padding: 0 10px; border: 0; border-radius: 9px; background: transparent; color: #a5b0ac; font-size: 11px; font-weight: 750; }
.mode-switch button.active { background: #2a3733; color: #f3f8f6; }
.view-rotate {
  position: absolute; z-index: 5; left: 10px; bottom: calc(10px + env(safe-area-inset-bottom)); width: 36px; height: 36px;
  display: grid; place-items: center; padding: 7px; appearance: none; border: 1px solid #ffffff1f; border-radius: 12px;
  background: #0d1210dd; backdrop-filter: blur(12px);
}
.view-rotate:active { background: #2a3733; transform: scale(.96); }
.view-rotate svg { width: 100%; height: 100%; fill: none; stroke: #eef6f3; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.keyboard-toggle {
  display: none; position: absolute; z-index: 5; left: 50%; bottom: calc(10px + env(safe-area-inset-bottom)); min-height: 36px;
  align-items: center; gap: 6px; padding: 0 11px; appearance: none; border: 1px solid #ffffff1f; border-radius: 12px;
  background: #0d1210dd; backdrop-filter: blur(12px); transform: translateX(-50%); font-size: 12px; font-weight: 750;
}
.keyboard-toggle.active { background: #28443b; border-color: #6de5bd55; }
.browser-shell.waiting .mode-switch,
.browser-shell.waiting .view-rotate,
.browser-shell.waiting .keyboard-toggle { display: none; }
.remote-cursor {
  position: absolute; left: 0; top: 0; z-index: 4; opacity: 0; pointer-events: none;
  transform-origin: 0 0; transition: opacity .1s;
}
.cursor-image { display: none; max-width: none; filter: drop-shadow(0 1px 1px #0008); }
.cursor-fallback { display: block; width: 32px; height: 40px; overflow: visible; filter: drop-shadow(0 1px 1px #0008); }
.cursor-fallback path { fill: #fff; stroke: #111513; stroke-width: 2.25; stroke-linejoin: round; }
.remote-cursor.has-image .cursor-image { display: block; }
.remote-cursor.has-image .cursor-fallback { display: none; }
.cursor-label {
  display: none; position: absolute; left: 17px; top: 18px; min-width: 22px; padding: 2px 5px; border: 1px solid #c8ffeb66;
  border-radius: 7px; background: #10a37f; box-shadow: 0 2px 7px #0008; color: #fff; font-size: 9px; font-weight: 900; text-align: center;
}
.remote-cursor.ai .cursor-fallback path { fill: #10a37f; stroke: #effff9; }
.remote-cursor.ai .cursor-label { display: block; }
.remote-cursor.visible { opacity: 1; }
.selection-actions {
  position: absolute; left: 0; top: 0; z-index: 6; display: flex; gap: 5px; opacity: 0; pointer-events: none; transition: opacity .12s;
}
.selection-actions.visible { opacity: 1; pointer-events: auto; }
.selection-actions button {
  min-height: 34px; padding: 0 12px; appearance: none; border: 1px solid #ffffff2b; border-radius: 10px;
  background: #111715f2; box-shadow: 0 4px 14px #0009; color: #fff; font-size: 12px; font-weight: 750;
}
#key-input { position: fixed; left: 50%; bottom: 1px; width: 2px; height: 2px; opacity: .01; resize: none; }
.pc-keyboard {
  display: none; position: relative; min-height: 0; padding: 16px max(7px, env(safe-area-inset-right)) max(7px, env(safe-area-inset-bottom)) max(7px, env(safe-area-inset-left));
  border-top: 1px solid #34413d; background: linear-gradient(#111614, #090c0b); box-shadow: 0 -8px 24px #0007;
}
.keyboard-resize {
  position: absolute; z-index: 3; top: -13px; right: max(9px, env(safe-area-inset-right)); width: 48px; height: 27px;
  display: grid; place-items: center; border: 1px solid #ffffff24; border-radius: 12px; background: #17201ddd;
  touch-action: none; cursor: ns-resize;
}
.keyboard-resize span { width: 23px; height: 3px; border-radius: 3px; background: #9caaa5; box-shadow: 0 -5px 0 #4e5d58, 0 5px 0 #4e5d58; }
.keyboard-rows { min-height: 0; display: grid; grid-template-rows: repeat(6, minmax(24px, 1fr)); gap: 4px; }
.keyboard-row { min-width: 0; display: flex; gap: 4px; }
.keyboard-row button {
  min-width: 0; flex: var(--key-flex) 1 0; padding: 0 3px; appearance: none; border: 1px solid #35413e; border-radius: 6px;
  background: linear-gradient(#252d2a, #171c1a); box-shadow: 0 2px 0 #070908; color: #e9efed; font-size: clamp(8px, 1.55vw, 11px); font-weight: 650;
  touch-action: manipulation; user-select: none; -webkit-user-select: none;
}
.keyboard-row button:active { transform: translateY(1px); box-shadow: 0 1px 0 #070908; background: #34413d; }
.keyboard-row button.modifier-active { border-color: #75e0bd; background: #245044; color: #fff; }
@keyframes turn { to { transform: rotate(360deg); } }

@media (orientation: landscape) {
  .address-row { padding-top: max(5px, env(safe-area-inset-top)); padding-left: max(8px, env(safe-area-inset-left)); padding-right: max(8px, env(safe-area-inset-right)); }
  .mode-switch { right: max(10px, env(safe-area-inset-right)); }
  .view-rotate { left: max(10px, env(safe-area-inset-left)); }
  .keyboard-toggle { display: flex; }
  .pc-keyboard.open { display: grid; }
}
